mapper.insert:
insert into co_create_rooms (
    room_code, owner_user_id, theme_snapshot, status, created_at, updated_at
) values (
    #{roomCode}, #{ownerUserId}, #{themeSnapshot}, #{status}, now(), now()
)

mapper.update:
update co_create_rooms
set theme_snapshot = #{themeSnapshot}, updated_at = now()
where id = #{roomId}

update co_create_rooms
set owner_user_id = #{ownerUserId}, updated_at = now()
where id = #{roomId}

mapper.delete:
delete from co_create_room_members
where room_id = #{roomId}
  and last_active_at is not null
  and last_active_at < #{cutoff}
